class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        self._used = {}  # month -> int
        self._files = {}  # month -> {name: size}
        self._current_month = {}  # name -> month (tracks latest month for a name)

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0.")
        files = self._files.setdefault(month, {})
        used = self._used.get(month, 0)
        if name in files:
            # Already counted for this month; don't count again.
            files[name] = size_bytes
            self._current_month[name] = month
            return
        if used + size_bytes > self._limit_bytes:
            raise ValueError("Monthly upload quota exceeded.")
        files[name] = size_bytes
        self._used[month] = used + size_bytes
        self._current_month[name] = month

    def delete(self, name: str, month: str) -> None:
        files = self._files.get(month)
        if files and name in files:
            del files[name]

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)
